// ---------------------------------------------------------------------
// C. PUBLIC FUNCTIONS (used by app.js)
// ---------------------------------------------------------------------
// Since they are not inside any block, these functions are GLOBAL:
// app.js, which loads afterwards, can call them directly.

/**
 * t("key", {placeholders}) → text in the active language.
 * If the translation is missing, Spanish is used; if that is missing too,
 * the key itself is returned (so an omission shows on screen instead of breaking anything).
 */
function t(clave, huecos = {}) {
  let texto = TEXTOS[idiomaActual][clave] ?? TEXTOS.es[clave] ?? clave;
  // Replaces each {name} with its value, like a Python f-string
  for (const [nombre, valor] of Object.entries(huecos)) {
    texto = texto.replaceAll(`{${nombre}}`, valor);
  }
  return texto;
}

/** locale() → "es-ES" or "en-GB", to format numbers in app.js */
function locale() {
  return LOCALES[idiomaActual];
}


// ---------------------------------------------------------------------
// D. APPLY A LANGUAGE TO THE PAGE
// ---------------------------------------------------------------------
function aplicarIdioma(idioma) {
  // If an unknown language arrives, Spanish by default
  if (!TEXTOS[idioma]) idioma = "es";
  idiomaActual = idioma;

  // D.1 lang attribute of <html>: used by screen readers
  //     (pronunciation) and by the browser's automatic translators
  document.documentElement.lang = idioma;

  // D.2 Plain texts: textContent replaces only the text
  document.querySelectorAll("[data-i18n]").forEach((el) => {
    el.textContent = t(el.dataset.i18n);
  });

  // D.3 Formatted texts (<b>…</b>): innerHTML interprets the tags.
  //     SECURITY: innerHTML only with OUR texts (this dictionary).
  //     Never with data coming from the API or the user: they could
  //     inject code into the page (XSS attack).
  //     data-i18n-html in the HTML → dataset.i18nHtml in JS (camelCase).
  document.querySelectorAll("[data-i18n-html]").forEach((el) => {
    el.innerHTML = t(el.dataset.i18nHtml);
  });

  // D.4 Mark the active button (the CSS highlights it with [aria-pressed="true"])
  document.querySelectorAll(".idioma").forEach((boton) => {
    boton.setAttribute("aria-pressed", String(boton.dataset.idioma === idioma));
  });

  // D.5 Remember the choice in the visitor's browser.
  //     try/catch: in private mode or with storage blocked,
  //     localStorage may throw an error; if so, the choice is simply not
  //     remembered, but the page keeps working.
  try { localStorage.setItem(CLAVE_ALMACEN, idioma); } catch { /* no memory, no problem */ }

  // D.6 Notify app.js so it repaints its texts and figures
  document.dispatchEvent(new CustomEvent("idioma-cambiado", { detail: { idioma } }));
}


// ---------------------------------------------------------------------
// E. INITIAL LANGUAGE AND FLAG BUTTONS
// ---------------------------------------------------------------------
// Priority: 1) what the visitor chose last time
//           2) their browser's language (Spanish → es; anything else → en)
function idiomaInicial() {
  try {
    const guardado = localStorage.getItem(CLAVE_ALMACEN);
    if (TEXTOS[guardado]) return guardado;
  } catch { /* storage not available */ }
  return (navigator.language || "es").toLowerCase().startsWith("es") ? "es" : "en";
}

// Each flag, when clicked, applies its language (data-idioma attribute)
document.querySelectorAll(".idioma").forEach((boton) => {
  boton.addEventListener("click", () => aplicarIdioma(boton.dataset.idioma));
});

// Startup: apply the initial language as soon as the page loads
aplicarIdioma(idiomaInicial());